SELECT (SELECT xyz FROM t0) AS t0_xyz, (SELECT a FROM t2) AS t2_a, (SELECT B FROM t2) AS t2_b, (SELECT count(*) FROM v2) AS v2_rows, (SELECT count(*) FROM v3) AS v3_rows, (SELECT count(*) FROM v4) AS v4_rows, (SELECT count(*) FROM v5) AS v5_rows, (SELECT a>=B FROM v2) AS v2_cmp, (SELECT a>=B FROM v3) AS v3_cmp, (SELECT a>=B FROM v4) AS v4_cmp, (SELECT a>=B FROM v5) AS v5_cmp, (SELECT count(*) FROM sqlite_schema WHERE type='table' AND name IN ('t0','t2')) AS table_count, (SELECT count(*) FROM sqlite_schema WHERE type='view' AND name IN ('v2','v3','v4','v5')) AS view_count;